using Nexcore.SharedKernel;
using Sales.Domain.Enums;

namespace Sales.Domain.Entities;

/// <summary>
/// Sales Quotation (RFQ response).
/// Aligned with SAP VA21 Quotation, Oracle Quote, Dynamics Sales Quote.
/// Can be converted to a Sales Order.
/// </summary>
public class Quotation : BaseEntity
{
    // ??? Identity ?????????????????????????????????????????????????????????????
    /// <summary>Auto-generated quotation number (e.g., QT-2024-00001).</summary>
    public string QuotationNumber { get; set; } = string.Empty;

    public string? QuotationName { get; set; }

    // ??? Customer ?????????????????????????????????????????????????????????????
    /// <summary>Cross-module reference to Crm.Contact. ID only.</summary>
    public Guid? ContactId { get; set; }
    /// <summary>Snapshot of contact name for fast reads.</summary>
    public string? ContactName { get; set; }

    // ??? Status & Dates ???????????????????????????????????????????????????????
    public QuotationStatus Status { get; set; } = QuotationStatus.Draft;

    public DateTime QuotationDate { get; set; } = DateTime.UtcNow;
    public DateTime? ValidUntil { get; set; }
    public DateTime? SentDate { get; set; }
    public DateTime? AcceptedDate { get; set; }

    // ??? Pricing ??????????????????????????????????????????????????????????????
    public Guid? PriceListId { get; set; }
    public PriceList? PriceList { get; set; }

    /// <summary>ISO 4217 currency code, e.g., "USD". No cross-module FK.</summary>
    public string CurrencyCode { get; set; } = "USD";

    /// <summary>Exchange rate to company base currency at quotation date.</summary>
    public decimal ExchangeRate { get; set; } = 1m;

    public PaymentTerms PaymentTerms { get; set; } = PaymentTerms.Net30;
    public Incoterm? Incoterm { get; set; }
    public string? IncotermLocation { get; set; }

    // ??? Delivery ?????????????????????????????????????????????????????????????
    public DateTime? RequestedDeliveryDate { get; set; }
    /// <summary>Cross-module FK to Crm.ContactAddress. ID only.</summary>
    public Guid? ShipToAddressId { get; set; }
    public string? ShippingMethod { get; set; }

    // ??? Financials ???????????????????????????????????????????????????????????
    public decimal SubtotalAmount { get; set; }
    public decimal DiscountAmount { get; set; }
    public decimal TaxAmount { get; set; }
    public decimal ShippingAmount { get; set; }
    public decimal TotalAmount { get; set; }

    // ??? Ownership ????????????????????????????????????????????????????????????
    public Guid? SalesRepId { get; set; }
    public Guid? SalesTerritoryId { get; set; }

    // ??? Traceability ?????????????????????????????????????????????????????????
    /// <summary>CRM Deal/Opportunity this quote originated from.</summary>
    public Guid? CrmDealId { get; set; }

    /// <summary>Sales Order generated from this quotation.</summary>
    public Guid? ConvertedToSalesOrderId { get; set; }

    public string? CustomerPONumber { get; set; }
    public string? CustomerPODate { get; set; }
    public string? Notes { get; set; }
    public string? TermsAndConditions { get; set; }

    // ??? Navigation ???????????????????????????????????????????????????????????
    public ICollection<QuotationLine> Lines { get; set; } = new List<QuotationLine>();
    public ICollection<QuotationApproval> Approvals { get; set; } = new List<QuotationApproval>();
}
